orca.default:
# once per coordinator terminal, if `orca orchestration run-current` shows none:
#   orca orchestration run-create --objective "<what this batch is for>" --json
WT=$(orca worktree create --name {name} --json | python3 -c 'import json,sys
def walk(n):
    if isinstance(n, dict):
        for k, v in n.items():
            if k == "path" and isinstance(v, str) and v.startswith("/"):
                return v
        for v in n.values():
            r = walk(v)
            if r: return r
    elif isinstance(n, list):
        for v in n:
            r = walk(v)
            if r: return r
print(walk(json.load(sys.stdin)) or "")')
STATE_DIR="${{XDG_STATE_HOME:-$HOME/.local/state}}/rightsize/launch"
OPTIONS_FILE="$STATE_DIR/{name}.rightsize-opencode.json"
OPENCODE_COMMAND="opencode -m {model_ref}"
if [ -n "$WT" ] && [ '__RIGHTSIZE_MODEL_OPTIONS__' != '{{}}' ]; then mkdir -p "$STATE_DIR"; printf '%s' '__RIGHTSIZE_MODEL_OPTIONS__' > "$OPTIONS_FILE"; OPENCODE_COMMAND="env OPENCODE_CONFIG=\"$OPTIONS_FILE\" $OPENCODE_COMMAND"; fi
HANDLE=$(orca terminal create --worktree name:{name} --command "$OPENCODE_COMMAND" --json | python3 -c 'import json,sys; print(json.load(sys.stdin)["result"]["terminal"]["handle"])')
orca orchestration worker-start --spec {spec} --worktree name:{name} --terminal "$HANDLE" --json

orca.codex:
# once per coordinator terminal, if `orca orchestration run-current` shows none:
#   orca orchestration run-create --objective "<what this batch is for>" --json
orca orchestration worker-start --spec {spec} --worktree new-child --name {name} --agent codex --json --model {model} --effort {effort}

orca.claude:
# once per coordinator terminal, if `orca orchestration run-current` shows none:
#   orca orchestration run-create --objective "<what this batch is for>" --json
orca orchestration worker-start --spec {spec} --worktree new-child --name {name} --agent claude --json --model {model} --effort {effort}
